import base64
import json
import os
from typing import Any, Dict, List, Optional, Union

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _read_document_bytes(document: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    if isinstance(document, str):
        if document.startswith("s3://"):
            raise ValueError(
                "S3 URIs are not supported by this function. Provide a local file path or raw bytes."
            )
        with open(document, "rb") as f:
            return f.read()
    raise TypeError("document must be a file path, bytes, or bytearray")


def _normalize_polygon(polygon: Any) -> Optional[List[Dict[str, float]]]:
    if not polygon:
        return None
    points = []
    for p in polygon:
        if isinstance(p, dict):
            x = p.get("X", p.get("x"))
            y = p.get("Y", p.get("y"))
        else:
            x = getattr(p, "X", getattr(p, "x", None))
            y = getattr(p, "Y", getattr(p, "y", None))
        if x is None or y is None:
            continue
        points.append({"x": float(x), "y": float(y)})
    return points or None


def _block_text(block: Any) -> str:
    txt = getattr(block, "Text", None)
    if txt is not None:
        return txt
    return getattr(block, "text", "") or ""


def _extract_cells_from_block(block: Any) -> List[Dict[str, Any]]:
    cells = []
    for cell in getattr(block, "Relationships", []) or []:
        rel_type = getattr(cell, "Type", None) or getattr(cell, "type", None)
        if rel_type == "CHILD":
            for cid in getattr(cell, "Ids", []) or getattr(cell, "ids", []) or []:
                # Caller handles lookup via block map
                cells.append({"_child_id": cid})
    return cells


def extract_table_cells_and_rows(
    document: Union[str, bytes, bytearray],
    *,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract table cells and row structure from a document using Amazon Textract.

    Returns a JSON-serializable dictionary with:
      - tables: list of tables, each with rows and cells
      - raw_blocks_count: number of Textract blocks returned
    """
    document_bytes = _read_document_bytes(document)

    textract = boto3.client("textract", region_name=region_name)

    try:
        response = textract.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=["TABLES"],
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Amazon Textract analyze_document failed: {e}") from e

    blocks = response.get("Blocks", []) or []
    block_map = {block["Id"]: block for block in blocks if "Id" in block}

    def get_block_text_by_relationship(block: Dict[str, Any]) -> str:
        text_parts: List[str] = []
        for rel in block.get("Relationships", []) or []:
            if rel.get("Type") == "CHILD":
                for child_id in rel.get("Ids", []) or []:
                    child = block_map.get(child_id)
                    if not child:
                        continue
                    if child.get("BlockType") == "WORD":
                        text_parts.append(child.get("Text", ""))
                    elif child.get("BlockType") == "SELECTION_ELEMENT":
                        if child.get("SelectionStatus") == "SELECTED":
                            text_parts.append("X")
        return " ".join(tp for tp in text_parts if tp).strip()

    tables_out: List[Dict[str, Any]] = []

    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        table = {
            "id": block.get("Id"),
            "confidence": block.get("Confidence"),
            "bounding_box": block.get("Geometry", {}).get("BoundingBox"),
            "polygon": _normalize_polygon(block.get("Geometry", {}).get("Polygon")),
            "rows": [],
        }

        cell_blocks: List[Dict[str, Any]] = []
        for rel in block.get("Relationships", []) or []:
            if rel.get("Type") == "CHILD":
                for cell_id in rel.get("Ids", []) or []:
                    cell = block_map.get(cell_id)
                    if cell and cell.get("BlockType") == "CELL":
                        cell_blocks.append(cell)

        rows: Dict[int, List[Dict[str, Any]]] = {}
        for cell in cell_blocks:
            row_index = int(cell.get("RowIndex", 0))
            col_index = int(cell.get("ColumnIndex", 0))
            cell_entry = {
                "id": cell.get("Id"),
                "row_index": row_index,
                "column_index": col_index,
                "row_span": int(cell.get("RowSpan", 1) or 1),
                "column_span": int(cell.get("ColumnSpan", 1) or 1),
                "text": get_block_text_by_relationship(cell),
                "confidence": cell.get("Confidence"),
                "bounding_box": cell.get("Geometry", {}).get("BoundingBox"),
                "polygon": _normalize_polygon(cell.get("Geometry", {}).get("Polygon")),
                "is_header": bool(cell.get("EntityTypes") and "COLUMN_HEADER" in cell.get("EntityTypes")),
            }
            rows.setdefault(row_index, []).append(cell_entry)

        for row_index in sorted(rows.keys()):
            row_cells = sorted(rows[row_index], key=lambda c: (c["column_index"], c["column_span"]))
            table["rows"].append(
                {
                    "row_index": row_index,
                    "cells": row_cells,
                }
            )

        tables_out.append(table)

    return {
        "tables": tables_out,
        "raw_blocks_count": len(blocks),
        "request_id": response.get("ResponseMetadata", {}).get("RequestId"),
    }
